// Verify the delivered ZIP contents through a temporary local web host, without Python/Core.
import { chromium } from '@playwright/test';
import { createServer } from 'node:http';
import { readFile,writeFile,mkdir } from 'node:fs/promises';
import { resolve,extname,sep } from 'node:path';
const directory=resolve(process.argv[2]||''),output=resolve(process.argv[3]||'.runtime/delivery/static-verification.json');
const server=createServer(async(request,response)=>{try{const path=resolve(directory,'.'+new URL(request.url,'http://localhost').pathname.replace(/\/$/,'/index.html'));if(!path.startsWith(directory+sep))throw Error('Invalid path');const body=await readFile(path);response.writeHead(200,{'Content-Type':({'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json'})[extname(path)]||'application/octet-stream'});response.end(body);}catch{response.writeHead(404);response.end();}});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
let browser;
try{const build=JSON.parse(await readFile(resolve(directory,'BUILD.json'),'utf8'));browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE||undefined,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']});const checks=[];
for(const width of [1280,390]){const context=await browser.newContext({viewport:{width,height:900},hasTouch:width<640,isMobile:width<640});const page=await context.newPage(),errors=[],api=[];page.on('pageerror',error=>errors.push(error.message));page.on('request',request=>{if(request.url().includes('/v1/'))api.push(request.url());});await page.goto(`http://127.0.0.1:${server.address().port}/?paused`,{waitUntil:'networkidle'});await page.waitForFunction(()=>window.entityPerformance?.frames>3);if(await page.locator('[data-store]').count()!==7)throw Error('Missing stores');await context.setOffline(true);if(width<640)await page.locator('#scene').tap();else await page.locator('#scene').click();await page.locator('#step').click();await page.locator('#ask').click();const state=await page.evaluate(()=>window.entityDiagnostics());if(state.world.scene!=='alert'||state.cameras.length!==5||!state.cameras.every(c=>c.revision===state.world.revision))throw Error('State/view divergence');if(!(await page.locator('#answer').innerText()).includes('Simulación local'))throw Error('Missing query evidence');if(errors.length||api.length)throw Error('Standalone app contacted Core or raised error');if(!await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth))throw Error('Viewport overflow');checks.push({width,cameras:state.cameras.length,mode:state.world.mode,offline_actions:'passed',core_requests:api.length,browser_errors:errors});await context.close();}
const report={status:'passed',source_commit:build.source_commit,package:'entity-experience.zip',checks,scope:'Chromium software render desktop/touch; offline after initial load, no offline reload guarantee'};await mkdir(resolve(output,'..'),{recursive:true});await writeFile(output,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}
